contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 tAmount) public {
        require(sender != address(0), "zero sender");
        require(recipient != address(0), "zero recipient");
        require(sender != recipient, "self transfer");
        require(tAmount > 0, "zero amount");

        uint256 senderBefore = c.balanceOf(sender);
        require(senderBefore >= tAmount, "insufficient sender balance");

        uint256 recipientBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transferFrom(sender, recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 senderAfter = c.balanceOf(sender);
            uint256 recipientAfter = c.balanceOf(recipient);
            assert(senderBefore - senderAfter == tAmount && recipientAfter - recipientBefore == tAmount);
        } else {
            assert(c.balanceOf(sender) == senderBefore && c.balanceOf(recipient) == recipientBefore);
        }
    }

    receive() external payable {}
}

