contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender, address recipient, uint256 amount) public {
        require(sender != address(0), "zero sender");
        require(recipient != address(0), "zero recipient");
        require(sender != recipient, "self transfer");
        require(amount > 0, "zero amount");

        uint256 senderBalBefore = c.balanceOf(sender);
        uint256 recipientBalBefore = c.balanceOf(recipient);
        uint256 txRewardRecipientBefore = c.txReward(recipient);

        bool reverted;
        try c.transfer(recipient, amount) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            uint256 senderBalAfter = c.balanceOf(sender);
            uint256 recipientBalAfter = c.balanceOf(recipient);
            uint256 txRewardRecipientAfter = c.txReward(recipient);

            // For unauthorized transfers (neither sender nor recipient has allowed role), the transfer
            // does not trigger a reward: recipient receives exactly `amount` and sender loses `amount`.
            // We assert the recipient's txReward is unchanged and the balance logic holds within rounding.
            assert(txRewardRecipientAfter == txRewardRecipientBefore);
            // The recipient's balance increases by at most amount and at least amount (integer math on reflections can round down)
            // but the total amount transferred must not exceed the original amount due to rounding.
            assert(recipientBalAfter >= recipientBalBefore);
            assert(recipientBalAfter - recipientBalBefore <= amount);
            // sender's balance decrease must be consistent (could be slightly more due to rounding)
            assert(senderBalBefore >= senderBalAfter);
            // The key general rule: when no reward is applied, the sum of balances changes by at most rounding error,
            // and the recipient does not receive an extra reward.
        } else {
            // if it reverts, the state must be unchanged
            assert(c.balanceOf(sender) == senderBalBefore);
            assert(c.balanceOf(recipient) == recipientBalBefore);
            assert(c.txReward(recipient) == txRewardRecipientBefore);
        }
    }
}

