contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address authorizedSender, address recipient, uint256 amount) public {
        // Assume authorizedSender and recipient are distinct, non-zero, and authorized.
        require(authorizedSender != address(0) && recipient != address(0) && authorizedSender != recipient);
        require(amount > 0);

        // Owner is this contract. Grant roles to sender and recipient.
        (bool successGrantSender, ) = address(c).call(abi.encodeWithSignature("setAllowedRole(address,bool)", authorizedSender, true));
        require(successGrantSender, "failed to grant sender role");
        (bool successGrantRecipient, ) = address(c).call(abi.encodeWithSignature("setAllowedRole(address,bool)", recipient, true));
        require(successGrantRecipient, "failed to grant recipient role");

        // Give the sender enough tokens so the transfer succeeds.
        (bool successMint, ) = address(c).call(abi.encodeWithSignature("mint(address,uint256)", authorizedSender, amount));
        require(successMint, "failed to mint");

        // Record balances before.
        uint256 senderBefore = c.balanceOf(authorizedSender);
        uint256 recipientBefore = c.balanceOf(recipient);

        // Perform the transfer from the authorized sender to the authorized recipient.
        c.transferFrom(authorizedSender, recipient, amount);

        // Record balances after.
        uint256 senderAfter = c.balanceOf(authorizedSender);
        uint256 recipientAfter = c.balanceOf(recipient);

        // General rule: the sum of balances is preserved for the transfer part
        // and the recipient's balance increases by at least the transferred amount
        // (reward may add more).
        assert(senderAfter + recipientAfter >= senderBefore + recipientBefore);
        assert(recipientAfter >= recipientBefore + amount);
        assert(c.txReward(recipient) >= 0); // always true, but kept for shape
    }

    receive() external payable {}
}

