contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 limit, uint256 amount) public {
        // Fresh deployment: sender is owner and has the entire supply,
        // so it can set the reward rate, the minimum transfer amount,
        // and approve this test contract to spend its tokens.
        c.setRewardRate(5);
        c.setMinTxnAmount(limit);
        require(limit <= amount, "amount must meet minTxnAmount");
        c.approve(address(this), amount);
        require(c.allowance(address(c.owner()), address(this)) == amount);

        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();
        uint256 expectedReward = amount * rewardRate / percent;

        uint256 cBalanceBefore = c.balanceOf(address(c));

        bool ok = c.transferFrom(address(c.owner()), address(this), amount);

        uint256 cBalanceAfter = c.balanceOf(address(c));
        uint256 recipientReward = c.txReward(address(this));

        // Transfer succeeds, the full amount leaves the owner, the reward is
        // credited to the transaction recipient, and the contract pays the
        // reward from its own balance if it has enough tokens.  Exact mirror:
        // txReward increases by exactly what the contract's balance falls by.
        assert(
            ok &&
            recipientReward == expectedReward &&
            cBalanceBefore - cBalanceAfter == recipientReward &&
            c.balanceOf(address(this)) >= recipientReward
        );
    }
}

