contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address a, address b, uint256 amt) public {
        // Need two distinct nonzero addresses for a meaningful transfer; otherwise zero amounts always revert.
        require(a != address(0) && b != address(0) && a != b);
        require(amt > 0);

        // Ensure a has enough token balance to attempt the transfer.
        uint256 balA = c.balanceOf(a);
        require(balA >= amt);

        uint256 balB = c.balanceOf(b);
        uint256 supplyBefore = c.totalSupply();

        // Attempt to transfer amt from a to b.  msg.sender is this test contract, not a,
        // so the only case that can succeed is when this test contract is an allowed role.
        bool reverted;
        try c.transferFrom(a, b, amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAAfter = c.balanceOf(a);
        uint256 balBAfter = c.balanceOf(b);

        // General rule: a transfer never creates or destroys tokens between the two parties
        // in a way that increases their combined balance beyond the capped reward.
        // The reward rate is at most the contract's configured reward rate (percent is a public constant-like value).
        uint256 rewardCap = 0;
        {
            uint256 rate = c.rewardRate();
            uint256 pct = c.percent();
            uint256 minTx = c.minTxnAmount();
            if (rate > 0 && pct > 0 && amt >= minTx) {
                rewardCap = amt * rate / pct;
            }
        }

        // The only source of new tokens is the contract's own balance, which is bounded by current supply.
        // Revert case must leave balances unchanged; success can at most add rewardCap to (a+b) combined
        // while never exceeding a's original balance plus the reward cap between them.
        uint256 combinedBefore = balA + balB;
        uint256 combinedAfter = balAAfter + balBAfter;

        if (reverted) {
            assert(balAAfter == balA && balBAfter == balB);
        } else {
            // On success, tokens are conserved from a to b, optionally plus a reward minted from the contract's balance.
            assert(combinedAfter <= combinedBefore + rewardCap);
            assert(balAAfter <= balA + rewardCap);
        }

        // Total supply must never increase: rewards come from the contract's own holdings, not from minting new supply.
        assert(c.totalSupply() <= supplyBefore);
    }

    receive() external payable {}
}

