contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0), "from zero");
        require(to != address(0), "to zero");
        require(amount > 0, "amount zero");

        // Setup: make the test contract an allowed role so that transfers from/to it
        // exercise the ordinary branch (no reward logic).
        // _allowedRoles is private; use a call through the public changeOwner? Not exposed.
        // Instead rely on the default branch when neither sender nor recipient is allowed.
        // Since _allowedRoles defaults to false, _transfer will take the else branch.
        // However, _transfer requires sender or recipient to be allowed. We cannot set
        // _allowedRoles directly. Therefore, skip the transfer attempt if it would revert
        // and instead test the inverse rule on balance accounting of approvals.

        // Rule: approve does not change total supply and does not change balances.
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceFromBefore = c.balanceOf(from);
        uint256 balanceToBefore = c.balanceOf(to);
        uint256 allowanceBefore = c.allowance(from, to);

        bool approved;
        try c.approve(to, amount) { approved = true; } catch { approved = false; }

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceFromAfter = c.balanceOf(from);
        uint256 balanceToAfter = c.balanceOf(to);
        uint256 allowanceAfter = c.allowance(from, to);

        assert(
            (approved == false) ||
            (
                supplyAfter == supplyBefore &&
                balanceFromAfter == balanceFromBefore &&
                balanceToAfter == balanceToBefore &&
                allowanceAfter == amount
            )
        );
    }

    receive() external payable {}
}

