        require(recipient != address(0), "recipient zero");
        require(amount > 0, "amount zero");
        uint256 senderBalanceBefore = c.balanceOf(address(this));
        require(senderBalanceBefore >= amount, "insufficient test balance");
        uint256 recipientBalanceBefore = c.balanceOf(recipient);
        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool recipientIsAllowedRole = recipient == address(this);
        bool senderIsAllowedRole = true;
        if (recipientIsAllowedRole || senderIsAllowedRole) {
            uint256 effectiveAmount = amount;
            uint256 rewardAmount = 0;
            if (recipientIsAllowedRole && amount >= c.minTxnAmount()) {
                rewardAmount = amount * c.rewardRate() / c.percent();
                if (c.balanceOf(address(c)) >= rewardAmount) {
                    // reward computed below from before-balances
                } else {
                    rewardAmount = 0;
                }
            }
            if (senderIsAllowedRole && amount >= c.minTxnAmount()) {
                rewardAmount = amount * c.rewardRate() / c.percent();
                if (c.balanceOf(address(c)) >= rewardAmount) {
                    // reward computed below from before-balances
                } else {
                    rewardAmount = 0;
                }
            }
            if (recipientIsAllowedRole) {
                assert(!reverted && c.balanceOf(recipient) == recipientBalanceBefore + amount + rewardAmount);
            } else {
                assert(!reverted && c.balanceOf(recipient) == recipientBalanceBefore + amount);
            }
        } else {
            assert(!reverted && c.balanceOf(recipient) == recipientBalanceBefore + amount);
        }
    }

