            uint256 thisBalanceAfter = c.balanceOf(address(this));
            uint256 toBalanceAfter = c.balanceOf(to);
            uint256 sumAfter = thisBalanceAfter + toBalanceAfter;
            // Sum of balances must be conserved for a normal transfer (no reward)
            assert(sumAfter == sumBefore);
        } else {
            // If it reverted, state must be unchanged
            uint256 thisBalanceAfter = c.balanceOf(address(this));
            uint256 toBalanceAfter = c.balanceOf(to);
            assert(thisBalanceAfter == thisBalanceBefore && toBalanceAfter == toBalanceBefore);
        }
    }

    receive() external payable {}
}

